d3-6de005f8418a', 2, 'noun', 'en', 'trait (of character)', 'Det er en god streg hos ham.', 'That is a good trait of his.'), ('kat', 'word', '2c8e3de3-a649-5c5d-92b3-61a99eae8690', 1, 'noun', 'en', 'cat', 'Min kat sover i sofaen.', 'My cat sleeps on the sofa.'), ('beregning', 'word', 'eaf60505-e258-57b0-85f9-ab1fe9db8a44', 1, 'noun', 'en', 'calculation', 'Det er en svær beregning.', 'It is a difficult calculation.'), ('værksted', 'word', 'f7daaf74-c416-53e3-a65e-e80e9a833181', 1, 'noun', 'et', 'workshop, garage', 'Bilen er på værksted.', 'The car is at the garage.'), ('favorit', 'word', '78b7caed-50ea-5240-bb36-229b2d391c90', 1, 'noun', 'en', 'favorite', 'Hun er min favorit i konkurrencen.', 'She is my favorite in the competition.'), ('palæstinensisk', 'word', '356c72a4-64e4-5856-b7c5-891a43899771', 1, 'adjective', null, 'Palestinian', 'De spiste palæstinensisk mad.', 'They ate Palestinian food.'), ('bydel', 'word', '1a107e84-25a8-5c44-87f8-eb5063bf560c', 1, 'noun', 'en', 'neighborhood, district (of a city)', 'Jeg bor i en hyggelig bydel.', 'I live in a cozy neighborhood.'), ('opgørelse', 'word', '8276ff1e-ceb6-5749-9c5a-36352e4b19b4', 1, 'noun', 'en', 'count, inventory', 'Vi skal lave en opgørelse over lageret.', 'We need to do an inventory count of the warehouse.'), ('opgørelse', 'word', '5efed639-6fd6-5f79-ba6f-655332b206d0', 2, 'noun', 'en', 'statement, summary (report)', 'Her er en opgørelse over udgifterne.', 'Here is a statement of the expenses.'), ('orientere', 'word', '0d077894-d314-53c0-906f-9d7f2de36edd', 1, 'verb', null, 'to inform, to brief', 'Jeg vil gerne orientere dig om sagen.', 'I would like to brief you on the matter.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'locale-en-2026-09-25' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
